cd repo/r
for k in "shipwreck|wreck of the|Kapitan|19th.century" "replica|drift test|windage test" "AIS|merchant|shipping lane|longline|fishing fleet|vessel transit" "contrail" "SBIRS|DSP satellite|spy satellite|early.warning satellite|infrared flash" "VIIRS|MODIS|Himawari|MTSAT|Meteosat|geostationary imag" "GDAS|ERA5|wind field|upper.air|radiosonde" "magnetic (track|heading)|true track|CMH|CMT|LNAV" "unexamined|not yet examined|in custody|handed over" "sea state|wave height|Beaufort|whitecap" "cloud cover|cloud mask|cloud-free" "121.5|guard frequency|mayday" "Cocos.*(airport|ADS-B)|ADS-B" "contacts? (reviewed|dismissed)|sonar contact|target list" "Rodrigues|Mauritius" "personal effect|passenger (item|belonging)|bag" "Christmas Island" ; do n=$(grep -rIl -i -E "$k" --include=*.md --include=*.toml --include=*.txt --include=*.py "Claude Science Project Sep 29" 2>/dev/null | wc -l); echo "$k : $n"; done